head.script:
scwin.screenId = "jldfil17200";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil17200.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_FileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_FileDown = async function () {
    try { return await $c.data.downFile("/common/irDataFileDown.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param filename realFilename
 * @returns
 * @hidden N
*/
scwin.fileDown = async function (filename, realFilename) {
    /* sdd-asis-lifecycle:begin fn_FileDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_FileDownReq').set('method', 'popupFileDown');
    (document.fileDownForm || { elements: [] }).action = '/common/irDataFileDown.do';
    $c.util.getComponent('dma_FileDownReq').set('filename', filename);
    $c.util.getComponent('dma_FileDownReq').set('realFilename', realFilename);
    { const nr = await scwin.tx_fn_FileDown(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/basicpopup/basicpopup.xml", { "method": 'popupFileDown', "filename": filename, "realFilename": realFilename }); } };
    /* sdd-asis-lifecycle:end */
};
